<?php
use App\Application\MarketData\Services\MarketDataEvidenceExportService;
use App\Infrastructure\Persistence\MarketData\EodCorrectionRepository;
use Illuminate\Support\Facades\DB;
use Tests\Support\UsesMarketDataMariaDb;
use Tests\Support\R0025SyntheticV2World;
use Carbon\Carbon;

class B19CorrectionMariaDbProofTest extends TestCase
{
    use UsesMarketDataMariaDb;
    private $dirs=[];
    protected function setUp(): void {parent::setUp();$this->bootMarketDataMariaDb();}
    protected function tearDown(): void {foreach($this->dirs as $d){foreach(glob($d.'/*') as $f)if(is_file($f))unlink($f);rmdir($d);}Carbon::setTestNow();$this->tearDownMarketDataMariaDb();parent::tearDown();}
    private function export($id,$name): array {
        $c=DB::table('eod_dataset_corrections')->where('correction_id',$id)->first();$inputs=['correction'=>$c,'prior'=>DB::table('eod_publications')->where('publication_id',$c->baseline_publication_id)->first(),'replacement'=>DB::table('eod_publications')->where('publication_id',$c->replacement_publication_id)->first(),'runs'=>DB::table('eod_runs')->whereIn('run_id',array_filter([$c->prior_run_id,$c->new_run_id]))->get()->all(),'pointer'=>DB::table('eod_current_publication_pointer')->where('trade_date',$c->trade_date)->first()];
        $d=sys_get_temp_dir().'/b19_corr_real_'.uniqid();$this->dirs[]=$d;app(MarketDataEvidenceExportService::class)->exportCorrectionEvidence($id,$d);$this->assertSame(json_encode($c),json_encode(DB::table('eod_dataset_corrections')->where('correction_id',$id)->first()));$this->assertSame(json_encode($inputs['prior']),json_encode(DB::table('eod_publications')->where('publication_id',$c->baseline_publication_id)->first()));
        if(getenv('B19_CORRECTION_CAPTURE')){$raw=base_path('storage/app/market-data/evidence/MD-B19-A001');foreach(glob($d.'/*') as $f)copy($f,$raw.'/E024_'.$name.'_'.basename($f));file_put_contents($raw.'/E024_'.$name.'_sources_before_export.json',json_encode($inputs,JSON_PRETTY_PRINT));}
        return [json_decode(file_get_contents($d.'/correction_evidence.json'),true),$d];
    }
    public function test_real_changed_unchanged_failed_and_historical_correction(): void {
        $pkg=R0025SyntheticV2World::packagePath();$oracle=json_decode(file_get_contents($pkg.'/expected/expected_publication_manifest.json'),true);$body=file_get_contents($pkg.'/inputs/provider_response.json');$date=json_decode(file_get_contents($pkg.'/inputs/synthetic_world.json'),true)['trade_date'];$status=200;$response=$body;
        $reasons=json_decode(file_get_contents($pkg.'/inputs/frozen_reason_registry.json'),true)['entries'];DB::table('eod_reason_codes')->delete();foreach(array_chunk($reasons,100) as $chunk)DB::table('eod_reason_codes')->insert($chunk);
        $w=R0025SyntheticV2World::build(['http_fetcher'=>function()use(&$response,&$status){return ['status'=>$status,'body'=>$response,'headers'=>['Content-Type: application/json']];}]);$base=$w['publication_id'];$baseRun=$w['run_id'];$repo=new EodCorrectionRepository();$request=$repo->createRequest($date,'DATASET_HASH_CREATED','Independent source close105 corrected to106','requester-C',$base,$baseRun);$cid=(int)$request->correction_id;
        try{$w['pipeline']->runDaily($date,'api',$cid);$this->fail('Unapproved correction must be refused');}catch(\RuntimeException $e){$this->assertStringContainsString('APPROVED',$e->getMessage());}$this->assertSame($base,(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id'));
        $repo->approve($cid,'approver-D');$changed=json_decode($body,true);$changed['chart']['result'][0]['indicators']['quote'][0]['close'][0]=106;$response=json_encode($changed);$run=$w['pipeline']->runDaily($date,'api',$cid);$new=(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id');$this->assertNotSame($base,$new);
        $old=DB::table('eod_publications')->where('publication_id',$base)->first();$next=DB::table('eod_publications')->where('publication_id',$new)->first();$newHashes=[];$oldHashes=[];foreach(['bars'=>'bars_batch_hash','indicators'=>'indicators_batch_hash','eligibility'=>'eligibility_batch_hash'] as $k=>$f){$oldHashes[$f]=$oracle['payload']['artifacts'][$k];$newHashes[$f]=$next->$f;$this->assertSame($oldHashes[$f],$old->$f);}$this->assertNotSame($oldHashes['bars_batch_hash'],$newHashes['bars_batch_hash']);$this->assertSame($base,(int)$next->supersedes_publication_id);$this->assertSame('SEALED',$next->seal_state);
        [$p,$dir]=$this->export($cid,'changed');$this->assertSame('ADMITTED_COMPLETE',$p['evidence_admission']['evidence_admission_state'],json_encode($p['evidence_admission']['missing_sections']));
        foreach(['correction_id'=>$cid,'trade_date'=>$date,'prior_run_id'=>$baseRun,'new_run_id'=>(int)$run->run_id,'prior_publication_version'=>1,'new_publication_version'=>2,'old_hashes'=>$oldHashes,'new_hashes'=>$newHashes,'publication_switch'=>true,'prior_publication_is_current'=>false,'new_publication_is_current'=>true] as $key=>$value)$this->assertSame($value,$p[$key],$key);
        $this->assertSame('approver-D',$p['approval']['approved_by']);$this->assertNotEmpty($p['approval']['approved_at']);$this->assertSame('Independent source close105 corrected to106',$p['correction_lifecycle']['reason_note']);$this->assertSame($base,$p['supersession']['supersedes_publication_id']);$this->assertSame($new,(int)$p['current_publication']['publication_id']);$this->assertSame('Publication hash set changed and requires audit comparison.',$p['comparison_summary']);
        $this->assertSame('RESOLVED',$p['baseline_historical_publication_proof']['proof_status']);$this->assertSame('RESOLVED',$p['candidate_historical_publication_proof']['proof_status']);$m=json_decode(file_get_contents($dir.'/artifact_manifest.json'),true);foreach($m['files'] as $f=>$v)$this->assertSame(hash('sha256',file_get_contents($dir.'/'.$f)),$v['sha256']);$this->assertSame($oracle['publication_manifest_hash'],$m['binding_contexts']['baseline']['bindings']['publication_manifest_hash']['value']);
        // Missing and contradictory source fields may remain readable, never complete.
        foreach(['approved_by'=>null,'approved_at'=>null,'prior_run_id'=>(int)$run->run_id,'correction_reason_code'=>'','status'=>'CONSUMED_CURRENT'] as $field=>$bad){$before=DB::table('eod_dataset_corrections')->where('correction_id',$cid)->value($field);try{DB::table('eod_dataset_corrections')->where('correction_id',$cid)->update([$field=>$bad]);[$badPack]=$this->export($cid,'bad_'.$field);$this->assertSame('ADMITTED_INCOMPLETE',$badPack['evidence_admission']['evidence_admission_state'],$field);}finally{DB::table('eod_dataset_corrections')->where('correction_id',$cid)->update([$field=>$before]);}}
        $unchanged=$repo->createRequest($date,'DATASET_HASH_CREATED','Independent unchanged source','requester-C',$new,(int)$run->run_id);$repo->approve($unchanged->correction_id,'approver-D');$same=$w['pipeline']->runDaily($date,'api',$unchanged->correction_id);[$u]=$this->export((int)$unchanged->correction_id,'unchanged');$this->assertSame('UNCHANGED',$u['changed_decision']);$this->assertFalse($u['publication_switch']);$this->assertNull($u['new_publication']);$this->assertSame($new,$u['correction_lifecycle']['preserved_publication_id']);$this->assertSame($new,(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id'));
        // A second real changed correction supersedes the first replacement; old switch remains true.
        $third=$repo->createRequest($date,'DATASET_HASH_CREATED','Independent source close107','requester-C',$new,(int)$run->run_id);$repo->approve($third->correction_id,'approver-D');$changed['chart']['result'][0]['indicators']['quote'][0]['close'][0]=107;$response=json_encode($changed);$latest=$w['pipeline']->runDaily($date,'api',$third->correction_id);$latestId=(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id');[$history]=$this->export($cid,'historical');$this->assertTrue($history['publication_switch']);$this->assertFalse($history['new_publication_is_current']);$this->assertSame($latestId,(int)$history['current_publication']['publication_id']);$this->assertSame($newHashes,$history['new_hashes']);$this->assertSame('ADMITTED_COMPLETE',$history['evidence_admission']['evidence_admission_state']);
        $failed=$repo->createRequest($date,'DATASET_HASH_CREATED','Independent rejected auth request','requester-C',$latestId,(int)$latest->run_id);$repo->approve($failed->correction_id,'approver-D');$status=401;try{$w['pipeline']->runDaily($date,'api',$failed->correction_id);$this->fail('Provider auth error must propagate');}catch(\App\Infrastructure\MarketData\Source\SourceAcquisitionException $e){$this->assertSame('RUN_SOURCE_AUTH_ERROR',$e->reasonCode());}[$f]=$this->export((int)$failed->correction_id,'failed');$this->assertFalse($f['publication_switch']);$this->assertSame('ADMITTED_INCOMPLETE',$f['evidence_admission']['evidence_admission_state']);$this->assertSame($latestId,(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id'));
    }
    public function test_real_impact_modes_require_safe_publication_lifecycle(): void {
        $pkg=R0025SyntheticV2World::packagePath();$response=file_get_contents($pkg.'/inputs/provider_response.json');$reasons=json_decode(file_get_contents($pkg.'/inputs/frozen_reason_registry.json'),true)['entries'];DB::table('eod_reason_codes')->delete();foreach(array_chunk($reasons,100) as $chunk)DB::table('eod_reason_codes')->insert($chunk);
        $w=R0025SyntheticV2World::build(['http_fetcher'=>function()use(&$response){return ['status'=>200,'body'=>$response,'headers'=>['Content-Type: application/json']];}]);
        $o=app(\App\Application\MarketData\Services\BackfillLifecycleOrchestrator::class);$prop=new \ReflectionProperty($o,'pipeline');$prop->setAccessible(true);$prop->setValue($o,$w['pipeline']);$method=new \ReflectionMethod($o,'executePublicationReprocessForCase');$method->setAccessible(true);
        $baseDate=DB::table('eod_publications')->where('publication_id',$w['publication_id'])->value('trade_date');$date='2026-03-24';$cal=(array)DB::table('md_market_calendar_revisions')->where('cal_date',$baseDate)->first();unset($cal['calendar_revision_id']);$cal['cal_date']=$date;$cal['revision_uid']=hash('sha256','independent-impact-calendar-'.$date);$cal['source_ref']='https://www.idx.co.id/test-calendar/'.$date;DB::table('md_market_calendar_revisions')->insert($cal);
        $input=json_decode($response,true);$input['chart']['result'][0]['timestamp'][0]+=86400;$response=json_encode($input);$import=$w['pipeline']->importDaily($date,'api');$this->assertNotSame('READABLE',$import->publishability_state);
        $case=['requested_date'=>$baseDate,'run_id'=>(int)$import->run_id,'import_status'=>'IMPORTED','publication_reprocess_state'=>'PENDING_PROMOTE','publication_reprocess_summary'=>['candidate_trade_dates'=>[$date]]];
        $non=$method->invoke($o,$case,'api',false,false,sys_get_temp_dir(),false);$this->assertSame('REPUBLISHED',$non['publication_reprocess_state'],json_encode($non));$this->assertSame('AUTOMATED_NON_READABLE_DATES',$non['publication_reprocess_republication_mode']);$pub=DB::table('eod_current_publication_pointer')->where('trade_date',$date)->first();$this->assertNotNull($pub);$this->assertSame('SEALED',DB::table('eod_publications')->where('publication_id',$pub->publication_id)->value('seal_state'));
        // A real approved import changes the bar. The lifecycle creates/approves its own correction for readable impact.
        $repo=new EodCorrectionRepository();$request=$repo->createRequest($date,'DATASET_HASH_CREATED','Controlled changed import before impact','input-author',(int)$pub->publication_id,(int)$pub->run_id);$repo->approve($request->correction_id,'input-approver');$input['chart']['result'][0]['indicators']['quote'][0]['close'][0]=106;$response=json_encode($input);$changed=$w['pipeline']->importDaily($date,'api',$request->correction_id);$case['run_id']=(int)$changed->run_id;$case['publication_reprocess_summary']['readable_correction_candidate_trade_dates']=[$date];
        $yes=$method->invoke($o,$case,'api',false,false,sys_get_temp_dir(),false);$this->assertSame('REPUBLISHED',$yes['publication_reprocess_state'],json_encode($yes));$this->assertSame('AUTOMATED_READABLE_CORRECTION',$yes['publication_reprocess_republication_mode']);$this->assertCount(1,$yes['publication_reprocess_correction_ids']);$auto=DB::table('eod_dataset_corrections')->where('correction_id',$yes['publication_reprocess_correction_id'])->first();$this->assertSame('system',$auto->approved_by);$this->assertSame('PUBLISHED',$auto->status);$replacement=(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id');$this->assertNotSame((int)$pub->publication_id,$replacement);
        $sync=new \ReflectionMethod($o,'syncPublicationReprocessNotes');$sync->setAccessible(true);$sync->invoke($o,$yes);$primary=DB::table('eod_runs')->where('run_id',$yes['run_id'])->first();$this->assertStringContainsString('publication_reprocess_republication_mode=AUTOMATED_READABLE_CORRECTION',$primary->notes);$d=sys_get_temp_dir().'/b19_impact_real_'.uniqid();$this->dirs[]=$d;app(MarketDataEvidenceExportService::class)->exportRunEvidence($yes['run_id'],$d);$sum=json_decode(file_get_contents($d.'/run_summary.json'),true);$this->assertSame('REPUBLISHED',$sum['publication_reprocess_summary']['execution_state']);$this->assertSame('AUTOMATED_READABLE_CORRECTION',$sum['publication_reprocess_summary']['republication_mode']);$this->assertSame([(int)$auto->correction_id],$sum['publication_reprocess_summary']['correction_ids']);$this->assertSame([$date],$sum['publication_reprocess_summary']['republished_trade_dates']);foreach(glob($d.'/*') as $f)$this->assertStringNotContainsString($response,file_get_contents($f));if(getenv('B19_CORRECTION_CAPTURE')){copy($d.'/run_summary.json',base_path('storage/app/market-data/evidence/MD-B19-A001/E024_impact_run_summary.json'));file_put_contents(base_path('storage/app/market-data/evidence/MD-B19-A001/E024_impact_primary_run_before_export.json'),json_encode($primary,JSON_PRETTY_PRINT));}
        // Missing correction infrastructure blocks only this case and never mutates the current pointer.
        $prop=new \ReflectionProperty($o,'corrections');$prop->setAccessible(true);$prop->setValue($o,null);$blocked=$method->invoke($o,$case,'api',false,false,sys_get_temp_dir(),false);$this->assertSame('FAILED',$blocked['publication_reprocess_state']);$this->assertSame($replacement,(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id'));$this->assertSame(0,$blocked['publication_reprocess_republished_trade_date_count']);
        $blockedCase=$case;$blockedCase['publication_reprocess_summary']['readable_correction_candidate_trade_dates']=[];$blockedCase['publication_reprocess_blocked_trade_dates']=$date;$explicit=$method->invoke($o,$blockedCase,'api',false,false,sys_get_temp_dir(),false);$this->assertSame('BLOCKED_REQUIRES_CORRECTION',$explicit['publication_reprocess_state']);$this->assertSame(0,$explicit['publication_reprocess_republished_trade_date_count']);$this->assertSame($replacement,(int)DB::table('eod_current_publication_pointer')->where('trade_date',$date)->value('publication_id'));
        // Independent replay root is mandatory; no current output may become a fixture.
        $replay=new \ReflectionMethod($o,'requireIndependentReplayFixture');$replay->setAccessible(true);try{$replay->invoke($o,null,$date,$replacement);$this->fail('Independent fixture required');}catch(\RuntimeException $e){$this->assertStringContainsString('INDEPENDENT_FIXTURE_ROOT_REQUIRED',$e->getMessage());}
        if(getenv('B19_CORRECTION_CAPTURE'))file_put_contents(base_path('storage/app/market-data/evidence/MD-B19-A001/E024_real_impact_modes.json'),json_encode(['input_case'=>$case,'non_readable'=>$non,'readable_correction'=>$yes,'blocked'=>$blocked,'explicit_block'=>$explicit,'auto_correction_primary'=>$auto,'current_pointer'=>DB::table('eod_current_publication_pointer')->where('trade_date',$date)->first()],JSON_PRETTY_PRINT));
    }
}
